using AtlasPca;
using Xunit;
using static AtlasPca.Corpus.Tests.Conf;
using JD = System.Collections.Generic.Dictionary<string, object?>;
using JL = System.Collections.Generic.List<object?>;

namespace AtlasPca.Corpus.Tests;

/// <summary>The agent-side signers at their edges, replayed through the public producer entry point: every expected output and
/// refusal text below was produced by the TypeScript reference (threshold.ts, pq.ts, agent-native.ts, intent-session.ts,
/// intent-required.ts, action-schema.ts, prohibitions.ts, policy-link.ts, mesh.ts, facade.ts) from the producer-vector keys.</summary>
public class SignerReferenceEdgeTests
{
    static JD Keys => D(Load("producer-vectors.json")["keys"]);
    static EdKey Ed(string name) => EdKey.FromSeed(Pca.B64uDecode(D(Keys[name])["seed"], 32)!);
    static string Canon(object? o) => Pca.Canonicalize(o);
    static JD Direct => D(Pca.ParseJson(DirectJson));

    [Fact]
    public void EveryEdgeCaseMatchesTheReference()
    {
        var keys = Keys;
        var cases = L(Pca.ParseJson(CasesJson));
        Assert.Equal(CaseCount, cases.Count);
        foreach (var c in cases)
        {
            var v = D(c);
            var name = (string)v["name"]!;
            var want = D(v["expect"]);
            Func<object?> run = () => ProducerVectors.Produce((string)v["op"]!, D(v["args"]), keys);
            if (want.Count == 1 && want.TryGetValue("error", out var err))
            {
                var e = Assert.Throws<ArgumentException>(() => run());
                Assert.True((string)err! == e.Message, $"{name}: {e.Message}");
            }
            else Assert.True(Canon(want) == Canon(run()), name);
        }
    }

    // delegate_suite without an alg is the ed25519 delegate: it reproduces the delegate vectors, with and without to_holder
    [Fact]
    public void TheSuiteDelegateReproducesTheDelegateVectors()
    {
        var doc = Load("producer-vectors.json");
        var keys = D(doc["keys"]);
        int with = 0, without = 0;
        foreach (var c in L(doc["cases"]))
        {
            var v = D(c);
            if ((string)v["op"]! != "delegate") continue;
            var a = D(v["args"]);
            if (a.GetValueOrDefault("to_holder") == null) without++; else with++;
            Assert.True(Canon(v["expect"]) == Canon(ProducerVectors.Produce("delegate_suite", a, keys)), (string)v["name"]!);
        }
        Assert.True(with >= 1 && without >= 1, $"with {with}, without {without}");
    }

    [Fact]
    public void AMeshProofSharesHeadsAndLeavesAndLeavesOutFalsySides()
    {
        var m = D(Direct["mesh"]);
        var chain = L(m["chain"]).Select(D).ToList();
        var hops = L(m["hops"]).Select(D).ToList();
        var action = D(m["action"]);
        Assert.Equal(Canon(m["out"]), Canon(Signers.AssembleMeshProof(chain, hops, action, Ed("agent"), L(m["pins"]))));
        // an empty pin-proof list is not carried
        Assert.Equal(Canon(m["nopins"]), Canon(Signers.AssembleMeshProof(chain, hops, action, Ed("agent"), new JL())));
        Assert.Equal((string)Direct["mesh_action"]!, Signers.SignMeshAction(chain, action, Ed("agent")));
    }

    // heads are keyed by signature and head: sig "a" over 12 and sig "a1" over 2 are two heads
    [Fact]
    public void AMeshHeadKeySeparatesTheSignatureFromTheHead()
    {
        var m = D(Direct["mesh_sep"]);
        var chain = L(m["chain"]).Select(D).ToList();
        Assert.Equal(Canon(m["out"]), Canon(Signers.AssembleMeshProof(chain, L(m["hops"]).Select(D), D(m["action"]), Ed("agent"))));
    }

    [Fact]
    public void ASessionGrantCarriesTheGivenAgentBindingAndRiskPolicy()
    {
        var doc = Load("producer-vectors.json");
        var a = D(L(doc["cases"]).Select(D).First(c => (string)c["name"]! == "session-grant-g0")["args"]);
        var binding = D(Pca.ParseJson("""{"operator":"acme"}"""));
        var risk = D(Pca.ParseJson("""{"bMax":2,"kappa":1,"lambda":0.001,"rho":0.5,"theta1":0.25,"theta2":0.6,"weights":{"alpha":0.25,"beta":0.2,"delta":0.2,"epsilon":0.1,"gamma":0.2,"zeta":0.05}}"""));
        var g = Signers.MintSessionGrant(SuiteKey.Ed25519(Ed("principal")), Ed("agent").Id, (string)a["session"]!, 0, (string)a["root"]!, (string)a["map_digest"]!,
            L(a["predicates"]), salt: (string)a["salt"]!, agentBinding: binding, riskPolicy: risk);
        Assert.Equal(Canon(Direct["grant_binding"]), Canon(new JD { ["grant"] = g.Grant, ["goal_salt"] = g.GoalSalt }));
    }

    [Fact]
    public void TheEd25519SchemaKeyEntryIsKidAlgAndPk()
    {
        Assert.Equal(Canon(Direct["schema_key"]), Canon(Signers.ActionSchemaKeyOf("site-k1", SuiteKey.Ed25519(Ed("site")))));
    }

